c('topn-rownum-trap', 'SELECT ENAME, SAL FROM EMP WHERE ROWNUM <= 3 ORDER BY SAL DESC');
c('topn-rownum-gt', 'SELECT COUNT(*) FROM EMP WHERE ROWNUM > 1');
c('topn-rownum-between', 'SELECT * FROM (SELECT ROWNUM RN, ENAME FROM (SELECT ENAME FROM EMP ORDER BY ENAME)) WHERE RN BETWEEN 4 AND 6');
c('topn-fetch-ties', 'SELECT ENAME, SAL FROM EMP ORDER BY SAL DESC FETCH FIRST 2 ROWS WITH TIES');
c('topn-fetch-ties2', 'SELECT ENAME, SAL FROM EMP ORDER BY SAL FETCH FIRST 3 ROWS WITH TIES');
c('topn-fetch-pct', 'SELECT ENAME, SAL FROM EMP ORDER BY SAL DESC, ENAME FETCH FIRST 20 PERCENT ROWS ONLY');
c('topn-offset-only', 'SELECT ENAME FROM EMP ORDER BY ENAME OFFSET 12 ROWS');
c('topn-rn-func', 'SELECT ENAME, SAL FROM (SELECT ENAME, SAL, DENSE_RANK() OVER (ORDER BY SAL DESC) DR FROM EMP) WHERE DR <= 3 ORDER BY SAL DESC, ENAME');
c('hq-basic', 'SELECT LEVEL, EMPNO, ENAME, MGR FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME');
c('hq-indent', "SELECT LPAD(' ', 2 * (LEVEL - 1)) || ENAME AS 조직도 FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME");
c('hq-reverse', "SELECT LEVEL, ENAME FROM EMP START WITH ENAME = 'SMITH' CONNECT BY PRIOR MGR = EMPNO");
c('hq-path', "SELECT ENAME, SYS_CONNECT_BY_PATH(ENAME, '/') P FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME");
c('hq-root-leaf', 'SELECT ENAME, CONNECT_BY_ROOT ENAME ROOT, CONNECT_BY_ISLEAF LEAF FROM EMP START WITH ENAME IN (\'JONES\', \'BLAKE\') CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME');
c('hq-prior-col', 'SELECT ENAME, PRIOR ENAME 관리자, LEVEL FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME');
c('hq-level-limit', 'SELECT LEVEL, ENAME FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR AND LEVEL <= 2 ORDER SIBLINGS BY ENAME');
c('hq-where-filter', "SELECT LEVEL, ENAME FROM EMP WHERE JOB <> 'MANAGER' START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME");
c('hq-prune', "SELECT LEVEL, ENAME FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR AND ENAME <> 'BLAKE' ORDER SIBLINGS BY ENAME");
c('hq-no-start', 'SELECT COUNT(*) FROM EMP CONNECT BY PRIOR EMPNO = MGR');
c('hq-level-count', 'SELECT LEVEL, COUNT(*) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR GROUP BY LEVEL ORDER BY LEVEL');
c('hq-dual-gen', 'SELECT LEVEL N FROM DUAL CONNECT BY LEVEL <= 5');
c('hq-connect-first', 'SELECT LEVEL, ENAME FROM EMP CONNECT BY PRIOR EMPNO = MGR START WITH ENAME = \'JONES\' ORDER SIBLINGS BY ENAME');
c('hq-loop', 'SELECT EMPNO FROM EMP CONNECT BY PRIOR EMPNO = EMPNO');
c('hq-level-nocb', 'SELECT LEVEL FROM DUAL');
c('hq-siblings-nocb', 'SELECT ENAME FROM EMP ORDER SIBLINGS BY ENAME');
c('hq-orderby', 'SELECT LEVEL, ENAME FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER BY LEVEL DESC, ENAME');
c('hq-isleaf-filter', 'SELECT ENAME FROM EMP WHERE CONNECT_BY_ISLEAF = 1 START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER BY ENAME');
c('hq-join-ansi', 'SELECT LEVEL, E.ENAME, D.DNAME FROM EMP E JOIN DEPT D ON E.DEPTNO = D.DEPTNO START WITH E.MGR IS NULL CONNECT BY PRIOR E.EMPNO = E.MGR ORDER SIBLINGS BY E.ENAME');
c('hq-rownum', 'SELECT ROWNUM, LEVEL, ENAME FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR ORDER SIBLINGS BY ENAME');
c('self-3level', 'SELECT E.ENAME 사원, M.ENAME 관리자, MM.ENAME 차상위 FROM EMP E, EMP M, EMP MM WHERE E.MGR = M.EMPNO AND M.MGR = MM.EMPNO ORDER BY E.ENAME');
c('self-3level-outer', 'SELECT E.ENAME, M.ENAME MGR1, MM.ENAME MGR2 FROM EMP E LEFT JOIN EMP M ON E.MGR = M.EMPNO LEFT JOIN EMP MM ON M.MGR = MM.EMPNO ORDER BY E.ENAME');
c('self-count-sub', 'SELECT M.ENAME, COUNT(*) 부하수 FROM EMP E JOIN EMP M ON E.MGR = M.EMPNO GROUP BY M.ENAME ORDER BY 2 DESC, 1');
c('hyp-rank', 'SELECT RANK(1500) WITHIN GROUP (ORDER BY SAL DESC) R, DENSE_RANK(1500) WITHIN GROUP (ORDER BY SAL DESC) DR FROM EMP');
c('hyp-rank-asc-tie', 'SELECT RANK(3000) WITHIN GROUP (ORDER BY SAL) R, DENSE_RANK(3000) WITHIN GROUP (ORDER BY SAL) DR, ROUND(PERCENT_RANK(3000) WITHIN GROUP (ORDER BY SAL), 4) PR, ROUND(CUME_DIST(3000) WITHIN GROUP (ORDER BY SAL), 4) CD FROM EMP');
c('hyp-rank-dept', 'SELECT DEPTNO, RANK(2000) WITHIN GROUP (ORDER BY SAL) R FROM EMP GROUP BY DEPTNO ORDER BY DEPTNO');
c('win-agg-where', 'SELECT ENAME FROM EMP WHERE SAL > AVG(SAL) OVER ()');
c('hq-agg-max-level', 'SELECT MAX(LEVEL) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR');
c('hq-agg-avg-level', 'SELECT AVG(LEVEL) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR');
c('hq-agg-leaf', 'SELECT SUM(CONNECT_BY_ISLEAF) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR');
c('hq-agg-prior', 'SELECT COUNT(PRIOR ENAME) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR');
c('hq-agg-root', "SELECT COUNT(DISTINCT CONNECT_BY_ROOT ENAME) FROM EMP START WITH ENAME IN ('JONES', 'BLAKE', 'CLARK') CONNECT BY PRIOR EMPNO = MGR");
c('hq-agg-dual', 'SELECT SUM(LEVEL) FROM DUAL CONNECT BY LEVEL <= 100');
c('hq-agg-dept', 'SELECT DEPTNO, MAX(LEVEL), COUNT(*) FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR GROUP BY DEPTNO ORDER BY DEPTNO');
c('hq-prior-level', 'SELECT ENAME, LEVEL, PRIOR LEVEL FROM EMP START WITH MGR IS NULL CONNECT BY PRIOR EMPNO = MGR AND LEVEL <= 2 ORDER SIBLINGS BY ENAME');
c('win-lag-frame', 'SELECT LAG(SAL) OVER (ORDER BY SAL ROWS 1 PRECEDING) FROM EMP');
c('win-rank-frame', 'SELECT RANK() OVER (ORDER BY SAL ROWS 1 PRECEDING) FROM EMP');
c('win-frame-rev1', 'SELECT SUM(SAL) OVER (ORDER BY SAL ROWS BETWEEN 1 FOLLOWING AND 1 PRECEDING) FROM EMP');
c('win-frame-rev2', 'SELECT SUM(SAL) OVER (ORDER BY SAL ROWS BETWEEN UNBOUNDED FOLLOWING AND CURRENT ROW) FROM EMP');
c('win-frame-rev3', 'SELECT SUM(SAL) OVER (ORDER BY SAL ROWS BETWEEN CURRENT ROW AND UNBOUNDED PRECEDING) FROM EMP');
c('win-frame-rev4', 'SELECT SUM(SAL) OVER (ORDER BY SAL ROWS BETWEEN CURRENT ROW AND 1 PRECEDING) FROM EMP');
c('win-frame-rev5', 'SELECT SUM(SAL) OVER (ORDER BY SAL ROWS BETWEEN 1 FOLLOWING AND CURRENT ROW) FROM EMP');
c('win-frame-rev6', 'SELECT SUM(SAL) OVER (ORDER BY SAL RANGE BETWEEN 1 FOLLOWING AND 1 PRECEDING) FROM EMP');
c('win-frame-ok-pp', 'SELECT ENAME, SUM(SAL) OVER (ORDER BY EMPNO ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) S FROM EMP WHERE DEPTNO = 30 ORDER BY EMPNO');
c('win-range-2keys', 'SELECT COUNT(*) OVER (ORDER BY SAL, ENAME RANGE BETWEEN 150 PRECEDING AND 150 FOLLOWING) FROM EMP');
c('win-range-date', 'SELECT ENAME, HIREDATE, COUNT(*) OVER (ORDER BY HIREDATE RANGE BETWEEN 30 PRECEDING AND CURRENT ROW) C FROM EMP ORDER BY HIREDATE, ENAME');
c('win-range-date-f', 'SELECT ENAME, COUNT(*) OVER (ORDER BY HIREDATE RANGE BETWEEN CURRENT ROW AND 60 FOLLOWING) C FROM EMP ORDER BY HIREDATE, ENAME');
c('win-rank-arg', 'SELECT RANK(1500) OVER (ORDER BY SAL DESC) FROM EMP');
c('win-dense-arg', 'SELECT DENSE_RANK(SAL) OVER (ORDER BY SAL) FROM EMP');
c('win-rn-arg', 'SELECT ROW_NUMBER(SAL) OVER (ORDER BY SAL) FROM EMP');
c('topn-ties-noorder', 'SELECT COUNT(*) FROM (SELECT ENAME, SAL FROM EMP FETCH FIRST 2 ROWS WITH TIES)');
c('topn-ties-noorder2', 'SELECT COUNT(*) FROM (SELECT ENAME FROM EMP WHERE DEPTNO = 10 FETCH FIRST 1 ROWS WITH TIES)');
c('win-rows-frac', 'SELECT ENAME, COUNT(*) OVER (ORDER BY EMPNO ROWS BETWEEN 0.5 PRECEDING AND 1.5 FOLLOWING) C FROM EMP WHERE DEPTNO = 10 ORDER BY EMPNO');
c('win-rows-frac2', 'SELECT ENAME, SUM(SAL) OVER (ORDER BY EMPNO ROWS BETWEEN 1.9 PRECEDING AND CURRENT ROW) S FROM EMP WHERE DEPTNO = 30 ORDER BY EMPNO');
c('win-range-desc', 'SELECT ENAME, SAL, COUNT(*) OVER (ORDER BY SAL DESC RANGE BETWEEN 300 PRECEDING AND 300 FOLLOWING) C FROM EMP ORDER BY SAL DESC, ENAME');
c('win-range-nulls', 'SELECT ENAME, COMM, COUNT(*) OVER (ORDER BY COMM RANGE BETWEEN 500 PRECEDING AND CURRENT ROW) C FROM EMP WHERE DEPTNO = 30 ORDER BY COMM, ENAME');
c('win-range-nulls-first', 'SELECT ENAME, COMM, COUNT(*) OVER (ORDER BY COMM NULLS FIRST RANGE BETWEEN CURRENT ROW AND 1000 FOLLOWING) C FROM EMP WHERE DEPTNO = 30 ORDER BY COMM NULLS FIRST, ENAME');
c('win-range-desc-nulls', 'SELECT ENAME, COMM, SUM(COMM) OVER (ORDER BY COMM DESC RANGE BETWEEN 200 PRECEDING AND 200 FOLLOWING) S FROM EMP WHERE DEPTNO = 30 ORDER BY COMM DESC, ENAME');
c('win-range-nulls-unb1', 'SELECT ENAME, COMM, SUM(SAL) OVER (ORDER BY COMM RANGE BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) S FROM EMP ORDER BY COMM, ENAME');
c('win-range-nulls-unb2', 'SELECT ENAME, COMM, COUNT(*) OVER (ORDER BY COMM RANGE BETWEEN 100 FOLLOWING AND UNBOUNDED FOLLOWING) C FROM EMP ORDER BY COMM, ENAME');
c('win-range-nulls-unb3', 'SELECT ENAME, COMM, COUNT(*) OVER (ORDER BY COMM DESC RANGE BETWEEN UNBOUNDED PRECEDING AND 100 PRECEDING) C FROM EMP ORDER BY COMM DESC, ENAME');
c('win-range-nulls-unb4', 'SELECT ENAME, COMM, COUNT(*) OVER (ORDER BY COMM NULLS FIRST RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) C FROM EMP ORDER BY COMM NULLS FIRST, ENAME');
c('win-range-nulls-unb5', 'SELECT ENAME, COMM, MIN(ENAME) OVER (ORDER BY COMM DESC NULLS LAST RANGE BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) M FROM EMP ORDER BY COMM DESC NULLS LAST, ENAME');
c('win-range-mgr-unb', 'SELECT ENAME, MGR, SUM(SAL) OVER (ORDER BY MGR RANGE BETWEEN 1 FOLLOWING AND UNBOUNDED FOLLOWING) S FROM EMP ORDER BY MGR, ENAME');
c('win-range-mgr-desc-unb', 'SELECT ENAME, MGR, COUNT(*) OVER (ORDER BY MGR DESC RANGE BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) C FROM EMP ORDER BY MGR DESC, ENAME');
c('win-range-part-nulls', 'SELECT DEPTNO, ENAME, COUNT(*) OVER (PARTITION BY DEPTNO ORDER BY COMM RANGE BETWEEN 100 FOLLOWING AND UNBOUNDED FOLLOWING) C FROM EMP ORDER BY DEPTNO, COMM, ENAME');
c('self-sal-gt-mgr', 'SELECT E.ENAME, E.SAL, M.ENAME, M.SAL FROM EMP E, EMP M WHERE E.MGR = M.EMPNO AND E.SAL > M.SAL ORDER BY E.ENAME');

// ── W7: PIVOT·UNPIVOT·정규 표현식 ──
c('pv-basic', 'SELECT * FROM (SELECT JOB, DEPTNO, SAL FROM EMP) PIVOT (SUM(SAL) FOR DEPTNO IN (10, 20, 30)) ORDER BY JOB');
c('pv-alias', 'SELECT * FROM (SELECT JOB, DEPTNO, SAL FROM EMP) PIVOT (SUM(SAL) FOR DEPTNO IN (10 AS D10, 20 AS D20, 30 AS D30)) ORDER BY JOB');
c('pv-count', 'SELECT * FROM (SELECT DEPTNO, JOB FROM EMP) PIVOT (COUNT(*) FOR JOB IN (\'CLERK\' AS CLERK, \'MANAGER\' AS MANAGER, \'SALESMAN\' AS SALESMAN)) ORDER BY DEPTNO');
c('pv-multi', 'SELECT * FROM (SELECT DEPTNO, JOB, SAL FROM EMP) PIVOT (SUM(SAL) AS S, COUNT(*) AS C FOR DEPTNO IN (10 AS D10, 20 AS D20)) ORDER BY JOB');
c('pv-noinline', 'SELECT COUNT(*) FROM EMP PIVOT (SUM(SAL) FOR DEPTNO IN (10 AS D10, 20 AS D20, 30 AS D30))');
c('pv-noalias-str', "SELECT * FROM (SELECT DEPTNO, JOB FROM EMP) PIVOT (COUNT(*) FOR JOB IN ('CLERK', 'ANALYST')) ORDER BY DEPTNO");
c('pv-total-only', 'SELECT * FROM (SELECT DEPTNO, SAL FROM EMP) PIVOT (SUM(SAL) FOR DEPTNO IN (10 AS D10, 20 AS D20, 30 AS D30, 40 AS D40))');
c('pv-where-after', 'SELECT * FROM (SELECT JOB, DEPTNO, SAL FROM EMP) PIVOT (MAX(SAL) FOR DEPTNO IN (10 AS D10, 20 AS D20)) WHERE D10 IS NOT NULL ORDER BY JOB');
c('pv-case-equiv', 'SELECT JOB, SUM(CASE WHEN DEPTNO = 10 THEN SAL END) D10, SUM(DECODE(DEPTNO, 20, SAL)) D20 FROM EMP GROUP BY JOB ORDER BY JOB');
c('unpv-basic', 'SELECT * FROM (SELECT DEPTNO, D10, D20 FROM (SELECT 1 DEPTNO, 100 D10, NULL D20 FROM DUAL UNION ALL SELECT 2, 200, 300 FROM DUAL)) UNPIVOT (AMT FOR COL IN (D10, D20)) ORDER BY DEPTNO, COL');
c('unpv-include', 'SELECT * FROM (SELECT 1 ID, 100 A, NULL B FROM DUAL) UNPIVOT INCLUDE NULLS (V FOR K IN (A, B)) ORDER BY K');
c('unpv-label', "SELECT * FROM (SELECT 1 ID, 100 A, 200 B FROM DUAL) UNPIVOT (V FOR K IN (A AS 'ALPHA', B AS 'BETA')) ORDER BY K");
c('unpv-roundtrip', 'SELECT * FROM (SELECT * FROM (SELECT JOB, DEPTNO, SAL FROM EMP) PIVOT (SUM(SAL) FOR DEPTNO IN (10 AS D10, 20 AS D20, 30 AS D30))) UNPIVOT (SAL FOR DEPTNO IN (D10, D20, D30)) ORDER BY JOB, DEPTNO');
c('re-like', "SELECT ENAME FROM EMP WHERE REGEXP_LIKE(ENAME, '^[AJ]') ORDER BY ENAME");
c('re-like-i', "SELECT ENAME FROM EMP WHERE REGEXP_LIKE(ENAME, 'a.{2}', 'i') ORDER BY ENAME");
c('re-like-end', "SELECT ENAME FROM EMP WHERE REGEXP_LIKE(ENAME, '(ER|NG)$') ORDER BY ENAME");
c('re-like-class', "SELECT COUNT(*) FROM EMP WHERE REGEXP_LIKE(TO_CHAR(EMPNO), '^[[:digit:]]{4}$')");
c('re-substr', "SELECT REGEXP_SUBSTR('SQLD-2026-11', '[0-9]+'), REGEXP_SUBSTR('SQLD-2026-11', '[0-9]+', 1, 2), REGEXP_SUBSTR('a1b22c333', '[[:digit:]]+', 1, 3), REGEXP_SUBSTR('KING', 'X') FROM DUAL");
c('re-substr-sub', "SELECT REGEXP_SUBSTR('kim@example.com', '([a-z]+)@([a-z.]+)', 1, 1, NULL, 2) FROM DUAL");
c('re-instr', "SELECT REGEXP_INSTR('SQLD-2026-11', '[0-9]'), REGEXP_INSTR('SQLD-2026-11', '-', 1, 2), REGEXP_INSTR('SQLD-2026-11', '[0-9]+', 1, 1, 1), REGEXP_INSTR('ABC', 'Z') FROM DUAL");
c('re-replace', "SELECT REGEXP_REPLACE('010-1234-5678', '[0-9]{4}$', '****'), REGEXP_REPLACE('a  b   c', ' +', ' '), REGEXP_REPLACE('ABCABC', 'B', 'x', 1, 2), REGEXP_REPLACE('kim lee', '(\\\\w+) (\\\\w+)', '\\\\2 \\\\1') FROM DUAL");
c('re-replace-emp', "SELECT ENAME, REGEXP_REPLACE(ENAME, '[AEIOU]', '*') M FROM EMP WHERE DEPTNO = 10 ORDER BY ENAME");
c('re-count', "SELECT REGEXP_COUNT('BANANA', 'A'), REGEXP_COUNT('BANANA', 'AN'), REGEXP_COUNT('banana', 'A', 1, 'i'), REGEXP_COUNT('BANANA', 'A', 3) FROM DUAL");
c('re-perl', "SELECT REGEXP_SUBSTR('abc 123 def', '\\\\d+'), REGEXP_COUNT('a b  c', '\\\\s'), REGEXP_SUBSTR('hello_world!', '\\\\w+') FROM DUAL");
c('re-null', "SELECT REGEXP_SUBSTR(NULL, 'A'), REGEXP_COUNT(NULL, 'A'), REGEXP_REPLACE('ABC', NULL, 'x') FROM DUAL");
c('re-like-select-err', "SELECT REGEXP_LIKE(ENAME, 'A') FROM EMP", { match: 'code' });

// ── W7: DML·TCL·DDL 시나리오(문장들을 한 세션에서 차례로) ──
const s = (id, ...script) => c(id, script.join(';\n'), { script });
s('dml-insert-select', "CREATE TABLE T_D AS SELECT * FROM DEPT WHERE 1 = 0", "INSERT INTO T_D VALUES (50, 'IT', 'SEOUL')", "INSERT INTO T_D (DEPTNO, DNAME) VALUES (60, 'HR')", "INSERT INTO T_D SELECT * FROM DEPT WHERE DEPTNO <= 20", 'SELECT * FROM T_D ORDER BY DEPTNO', 'DROP TABLE T_D PURGE');
s('dml-update', 'CREATE TABLE T_E AS SELECT EMPNO, ENAME, SAL, COMM, DEPTNO FROM EMP', 'UPDATE T_E SET SAL = SAL * 1.1 WHERE DEPTNO = 10', 'UPDATE T_E SET SAL = SAL + 100, COMM = NVL(COMM, 0) WHERE JOB_DUMMY = 1', "UPDATE T_E SET COMM = 0 WHERE COMM IS NULL", 'SELECT ENAME, SAL, COMM FROM T_E WHERE DEPTNO IN (10, 30) ORDER BY EMPNO', 'DROP TABLE T_E PURGE');
s('dml-update-sub', 'CREATE TABLE T_E AS SELECT EMPNO, ENAME, SAL, DEPTNO FROM EMP', 'UPDATE T_E E SET SAL = (SELECT MAX(SAL) FROM EMP X WHERE X.DEPTNO = E.DEPTNO) WHERE E.DEPTNO = 20', "UPDATE T_E SET (SAL, DEPTNO) = (SELECT SAL, DEPTNO FROM EMP WHERE ENAME = 'KING') WHERE ENAME = 'SMITH'", 'SELECT ENAME, SAL, DEPTNO FROM T_E WHERE DEPTNO IN (10, 20) ORDER BY ENAME', 'DROP TABLE T_E PURGE');
s('dml-delete-truncate', 'CREATE TABLE T_E AS SELECT * FROM EMP', 'DELETE FROM T_E WHERE DEPTNO = 30', 'DELETE T_E WHERE SAL < 1000', 'SELECT COUNT(*) FROM T_E', 'ROLLBACK', 'SELECT COUNT(*) FROM T_E', 'TRUNCATE TABLE T_E', 'SELECT COUNT(*) FROM T_E', 'DROP TABLE T_E PURGE', 'SELECT COUNT(*) FROM T_E');
s('dml-merge', 'CREATE TABLE T_D AS SELECT * FROM DEPT WHERE DEPTNO <= 20', "UPDATE T_D SET LOC = 'OLD'", "MERGE INTO T_D T USING DEPT S ON (T.DEPTNO = S.DEPTNO) WHEN MATCHED THEN UPDATE SET T.LOC = S.LOC WHEN NOT MATCHED THEN INSERT (DEPTNO, DNAME, LOC) VALUES (S.DEPTNO, S.DNAME, S.LOC)", 'SELECT * FROM T_D ORDER BY DEPTNO', 'DROP TABLE T_D PURGE');
s('dml-merge-where', 'CREATE TABLE T_D AS SELECT * FROM DEPT WHERE DEPTNO <= 20', "MERGE INTO T_D T USING (SELECT * FROM DEPT) S ON (T.DEPTNO = S.DEPTNO) WHEN MATCHED THEN UPDATE SET T.DNAME = LOWER(S.DNAME) WHERE S.DEPTNO = 10 WHEN NOT MATCHED THEN INSERT VALUES (S.DEPTNO, S.DNAME, S.LOC) WHERE S.DEPTNO = 40", 'SELECT * FROM T_D ORDER BY DEPTNO', 'DROP TABLE T_D PURGE');
s('tcl-savepoint', "INSERT INTO DEPT VALUES (50, 'IT', 'SEOUL')", 'SAVEPOINT A', "INSERT INTO DEPT VALUES (60, 'HR', 'BUSAN')", 'SAVEPOINT B', 'DELETE FROM DEPT WHERE DEPTNO = 40', 'ROLLBACK TO B', 'SELECT DEPTNO FROM DEPT ORDER BY 1', 'ROLLBACK TO A', 'SELECT DEPTNO FROM DEPT ORDER BY 1', 'ROLLBACK TO B', 'ROLLBACK', 'SELECT COUNT(*) FROM DEPT');
s('tcl-commit-rollback', 'CREATE TABLE T_D AS SELECT * FROM DEPT', 'DELETE FROM T_D WHERE DEPTNO = 40', 'COMMIT', "INSERT INTO T_D VALUES (50, 'IT', 'SEOUL')", 'ROLLBACK', 'SELECT DEPTNO FROM T_D ORDER BY 1', 'DROP TABLE T_D PURGE');
s('tcl-ddl-commits', 'CREATE TABLE T_D AS SELECT * FROM DEPT', "INSERT INTO T_D VALUES (50, 'IT', 'SEOUL')", 'CREATE TABLE T_X (A NUMBER)', 'ROLLBACK', 'SELECT COUNT(*) FROM T_D', 'DROP TABLE T_X PURGE', 'DROP TABLE T_D PURGE');
s('ddl-constraints', "CREATE TABLE T_X (ID NUMBER(3) CONSTRAINT PK_TX PRIMARY KEY, NM VARCHAR2(5) NOT NULL, AMT NUMBER(5,2) CONSTRAINT CK_TX CHECK (AMT >= 0), D NUMBER(2) CONSTRAINT FK_TX REFERENCES DEPT(DEPTNO))", "INSERT INTO T_X VALUES (1, 'A', 1, 10)", "INSERT INTO T_X VALUES (1, 'B', 1, 10)", "INSERT INTO T_X (ID, NM) VALUES (2, NULL)", "INSERT INTO T_X VALUES (3, 'TOOLONG', 1, 10)", "INSERT INTO T_X VALUES (4, 'C', -1, 10)", "INSERT INTO T_X VALUES (5, 'D', 1000, 10)", "INSERT INTO T_X VALUES (6, 'E', 1, 99)", 'UPDATE T_X SET NM = NULL', "INSERT INTO T_X VALUES (7, 'F', 1.234, 20)", 'SELECT * FROM T_X ORDER BY 1', 'DROP TABLE T_X PURGE');
s('ddl-default-fk', "CREATE TABLE T_P (PID NUMBER PRIMARY KEY, PNAME VARCHAR2(10))", "CREATE TABLE T_C (CID NUMBER, PID NUMBER CONSTRAINT FK_TC REFERENCES T_P ON DELETE CASCADE, CNT NUMBER DEFAULT 0, HD DATE DEFAULT DATE '2026-01-01')", "INSERT INTO T_P VALUES (1, 'A')", "INSERT INTO T_P VALUES (2, 'B')", 'INSERT INTO T_C (CID, PID) VALUES (10, 1)', 'INSERT INTO T_C VALUES (11, 2, DEFAULT, DEFAULT)', 'INSERT INTO T_C (CID, PID, CNT) VALUES (12, 2, 5)', 'SELECT * FROM T_C ORDER BY CID', 'DELETE FROM T_P WHERE PID = 2', 'SELECT * FROM T_C ORDER BY CID', 'DROP TABLE T_P', 'DROP TABLE T_P CASCADE CONSTRAINTS PURGE', 'DROP TABLE T_C PURGE');
s('ddl-setnull', "CREATE TABLE T_P (PID NUMBER PRIMARY KEY)", "CREATE TABLE T_C (CID NUMBER, PID NUMBER REFERENCES T_P ON DELETE SET NULL)", 'INSERT INTO T_P VALUES (1)', 'INSERT INTO T_C VALUES (10, 1)', 'DELETE FROM T_P', 'SELECT * FROM T_C', 'DROP TABLE T_C PURGE', 'DROP TABLE T_P PURGE');
s('ddl-alter', "CREATE TABLE T_X AS SELECT EMPNO, ENAME FROM EMP WHERE DEPTNO = 10", 'ALTER TABLE T_X ADD (BONUS NUMBER(5) DEFAULT 100)', 'ALTER TABLE T_X ADD (MEMO VARCHAR2(10) NOT NULL)', 'ALTER TABLE T_X MODIFY (ENAME VARCHAR2(20))', 'ALTER TABLE T_X MODIFY (ENAME VARCHAR2(3))', 'ALTER TABLE T_X RENAME COLUMN BONUS TO BONUS_AMT', 'ALTER TABLE T_X DROP COLUMN EMPNO', 'SELECT * FROM T_X ORDER BY ENAME', 'RENAME T_X TO T_Y', 'SELECT COUNT(*) FROM T_Y', 'DROP TABLE T_Y PURGE');
s('ddl-add-constraint', "CREATE TABLE T_X AS SELECT EMPNO, ENAME, DEPTNO FROM EMP", 'ALTER TABLE T_X ADD CONSTRAINT PK_TX PRIMARY KEY (EMPNO)', 'ALTER TABLE T_X ADD CONSTRAINT UQ_TX UNIQUE (DEPTNO)', 'ALTER TABLE T_X ADD CONSTRAINT CK_TX CHECK (DEPTNO > 10)', 'ALTER TABLE T_X ADD CONSTRAINT FK_TX FOREIGN KEY (DEPTNO) REFERENCES DEPT(DEPTNO)', "INSERT INTO T_X VALUES (7369, 'DUP', 10)", 'ALTER TABLE T_X DROP CONSTRAINT PK_TX', "INSERT INTO T_X VALUES (7369, 'DUP', 10)", 'SELECT COUNT(*) FROM T_X', 'DROP TABLE T_X PURGE');
s('ddl-ctas-notnull', 'CREATE TABLE T_X AS SELECT EMPNO, ENAME, SAL * 12 ANNUAL FROM EMP WHERE DEPTNO = 10', 'INSERT INTO T_X (ENAME) VALUES (\'NOPK\')', 'INSERT INTO T_X (EMPNO, ENAME) VALUES (7839, \'DUP\')', 'SELECT COUNT(*) FROM T_X', 'DROP TABLE T_X PURGE');
s('ddl-view', "CREATE VIEW T_V AS SELECT EMPNO, ENAME, DEPTNO FROM EMP WHERE DEPTNO = 10", 'SELECT * FROM T_V ORDER BY EMPNO', "CREATE OR REPLACE VIEW T_V AS SELECT DEPTNO, COUNT(*) CNT FROM EMP GROUP BY DEPTNO", 'SELECT * FROM T_V ORDER BY DEPTNO', 'DROP VIEW T_V', 'SELECT * FROM T_V');
