// ── SQL 실습장 과제의 모범 답안 ──
const TASKS = JSON.parse(readFileSync(new URL('../../src/lib/sql-lab/tasks.json', import.meta.url), 'utf8'));
for (const set of TASKS) {
  for (const item of set.items) {
    if (item.check) {
      // 데이터를 바꾸는 과제: 모범 답안 문장들 → 확인 쿼리를 한 세션에서
      const script = [...splitSqlTask(item.answer), item.check];
      c(`task-${set.id}-${item.id}`, script.join(';\n'), { script });
    } else c(`task-${set.id}-${item.id}`, item.answer.replace(/;\s*$/, ''));
  }
}
function splitSqlTask(text) {
  return text.split(/;\s*/).map((x) => x.trim()).filter(Boolean);
}

// ── 노트의 ```sql 블록: 노트 예제를 실습장에서 돌렸을 때도 Oracle 과 같아야 한다 ──
const NOTES = new URL('../../content/aws-certs/sqld/', import.meta.url);
const splitSql = (text) => text.split(/;\s*(?:\n|$)/).map((x) => x.trim()).filter(Boolean);
const stripComments = (s) => s.replace(/^(?:--[^\n]*\n|\s)+/, '');
for (const week of readdirSync(NOTES).filter((w) => /^week\d+$/.test(w)).sort()) {
  for (const file of readdirSync(new URL(`${week}/`, NOTES)).filter((f) => /^day\d+\.md$/.test(f)).sort()) {
    const body = readFileSync(new URL(`${week}/${file}`, NOTES), 'utf8').replace(/\r\n/g, '\n').split(/\n## .*연습 문제/)[0];
    let n = 0;
    for (const m of body.matchAll(/```sql\n([\s\S]*?)```/g)) {
      const stmts = splitSql(m[1]).filter((s) => !/^SET\s/i.test(stripComments(s)));
      // 데이터·구조를 바꾸는 블록은 문장들을 한 세션에서 차례로 대조한다.
      if (stmts.some((s) => !/^(SELECT|WITH|\()/i.test(stripComments(s)))) {
        c(`note-${week.replace('week', 'w')}${file.replace('day', 'd').replace('.md', '')}-${++n}`, stmts.join(';\n'), { script: stmts, note: true });
        continue;
      }
      for (const stmt of stmts) {
        if (!/^(SELECT|WITH|\()/i.test(stripComments(stmt))) continue;
        c(`note-${week.replace('week', 'w')}${file.replace('day', 'd').replace('.md', '')}-${++n}`, stmt, { match: 'code', note: true });
      }
    }
  }
}

